from datetime import datetime
from pathlib import Path
import sqlite3

import config
import uniclubs_catalog


SCHEMA = (
    '''CREATE TABLE IF NOT EXISTS plans (
        id INTEGER PRIMARY KEY,
        owner TEXT NOT NULL CHECK (trim(owner) <> ''),
        user_id INTEGER NOT NULL CHECK (user_id > 0),
        event_id TEXT NOT NULL CHECK (event_id LIKE 'uniclubs:%' AND length(event_id) > 9),
        status TEXT NOT NULL CHECK (status IN ('confirmed','cancelled','attended','not_attended')),
        rating INTEGER CHECK (rating BETWEEN 1 AND 5),
        confirmed_at TEXT NOT NULL,
        answered_at TEXT,
        UNIQUE (owner, event_id),
        CHECK (rating IS NULL OR status='attended')
    )''',
    '''CREATE TABLE IF NOT EXISTS favorites (
        owner TEXT NOT NULL CHECK (trim(owner) <> ''),
        kind TEXT NOT NULL CHECK (kind IN ('series','club')),
        target_key TEXT NOT NULL CHECK (trim(target_key) <> ''),
        PRIMARY KEY (owner, kind, target_key)
    )''',
    '''CREATE TABLE IF NOT EXISTS settings (
        owner TEXT PRIMARY KEY NOT NULL CHECK (trim(owner) <> ''),
        ratings_revision INTEGER NOT NULL DEFAULT 0 CHECK (ratings_revision >= 0)
    )''',
)


def get_connection(db_file=None):
    """Open the ignored private state file or an isolated ':memory:' database."""
    if db_file is None:
        db_file = config.UNICLUBS_USER_DB_FILE
    if str(db_file) != ':memory:':
        path = Path(db_file).resolve()
        if path in (config.DB_FILE.resolve(), config.UNICLUBS_DB_FILE.resolve()):
            raise ValueError('UniClubs private state needs its own database file.')
        path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(str(db_file), check_same_thread=False)
    connection.execute('PRAGMA foreign_keys=1')
    connection.row_factory = sqlite3.Row
    return connection


def init_db(connection):
    """Create private tables without committing or discarding another pending transaction."""
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before initializing private state.')
    with connection:
        connection.execute('BEGIN')
        for statement in SCHEMA:
            connection.execute(statement)


def _owner(value):
    """Require an explicit nonempty owner token rather than sharing unnamed state."""
    if not isinstance(value, str) or not value.strip():
        raise ValueError('A private owner token is required.')
    return value.strip()


def _event_id(value):
    """Require the public source namespace for every private event reference."""
    if not uniclubs_catalog.is_catalog_id(value):
        raise ValueError('A namespaced UniClubs event ID is required.')
    return value


def get_interaction(connection, owner, event_id):
    """Return one owner's event state, or None when the event has not been planned."""
    row = connection.execute('SELECT * FROM plans WHERE owner=? AND event_id=?',
                             (_owner(owner), _event_id(event_id))).fetchone()
    return dict(row) if row is not None else None


def list_interactions(connection, owner):
    """Read only this owner's private states, without joining public event metadata."""
    rows = connection.execute('SELECT * FROM plans WHERE owner=? ORDER BY confirmed_at,id',
                              (_owner(owner),)).fetchall()
    return [dict(row) for row in rows]


def _validate_action(user_id, event, action, rating, now):
    """Validate source identity, normal action names and naive local event boundaries."""
    if type(user_id) is not int or user_id < 1:
        raise ValueError('A positive user ID is required.')
    _event_id(getattr(event, 'event_id', None))
    if not isinstance(action, str) or action not in config.INTERACTION_TRANSITIONS:
        raise ValueError('Unknown interaction action.')
    if action == 'rate':
        if type(rating) is not int or not config.RATING_MIN <= rating <= config.RATING_MAX:
            raise ValueError('Rating must be an integer from 1 to 5.')
    elif rating is not None:
        raise ValueError('Use the rate action to save a rating.')
    for moment in (getattr(event, 'start', None), getattr(event, 'end', None), now):
        if not isinstance(moment, datetime) or moment.tzinfo is not None:
            raise ValueError('Private planning uses naive Zurich datetimes.')
    if event.end <= event.start:
        raise ValueError('The event interval must be positive.')


def _validate_transition(previous, user_id, event, action, now):
    """Apply the existing action/time rules while keeping source availability distinct."""
    status = previous['status'] if previous else None
    if previous is not None and previous['user_id'] != user_id:
        raise ValueError('The private owner does not belong to this user.')
    if status not in config.INTERACTION_TRANSITIONS[action]:
        raise ValueError('This action is not available in the current event state.')
    if action in ('confirm', 'cancel') and event.start <= now:
        raise ValueError('This event has already started.')
    if action == 'confirm' and not getattr(event, 'can_confirm', False):
        raise ValueError('This source event cannot currently be confirmed.')
    if action in ('attended', 'not_attended', 'rate'):
        multi_day = getattr(event, 'is_multi_day', lambda: False)()
        if (getattr(event, 'source_cancelled', False)
                or getattr(event, 'end_is_estimated', False) or multi_day):
            raise ValueError('Feedback requires a non-cancelled event with a known single-day end.')
    if action in ('attended', 'not_attended', 'rate') and event.end >= now:
        raise ValueError('Feedback can be saved only after the event has ended.')


def save_interaction(connection, owner, user_id, event, action, rating=None, now=None):
    """Save an owner-scoped transition and increment revision only for an effective rating.

    :param connection: private state connection
    :param owner: stable opaque profile token, supplied by the caller
    :param user_id: positive local profile ID, stored for private feedback processing
    :param event: source-aware domain event, never copied into this private table
    :param action: confirm, cancel, attended, not_attended or rate
    :param rating: integer 1–5 only for rate
    :param now: optional naive Zurich clock
    :return: saved interaction dictionary
    """
    owner, now = _owner(owner), config.local_now(now)
    _validate_action(user_id, event, action, rating, now)
    with connection:
        previous = get_interaction(connection, owner, event.event_id)
        _validate_transition(previous, user_id, event, action, now)
        _write_interaction(connection, owner, user_id, event, action, rating, previous, now)
        if action == 'rate' and previous['rating'] != rating:
            connection.execute('''INSERT INTO settings (owner, ratings_revision) VALUES (?,1)
                ON CONFLICT(owner) DO UPDATE SET ratings_revision=ratings_revision+1''', (owner,))
    return get_interaction(connection, owner, event.event_id)


def _write_interaction(connection, owner, user_id, event, action, rating, previous, now):
    """Write one validated transition inside the caller's transaction."""
    stamp = now.strftime(config.DB_TIME_FORMAT)
    confirmed = stamp if action == 'confirm' else previous['confirmed_at']
    answered = previous['answered_at'] if previous else None
    if action in ('attended', 'not_attended'):
        answered = stamp
    connection.execute('''INSERT INTO plans
        (owner,user_id,event_id,status,rating,confirmed_at,answered_at) VALUES (?,?,?,?,?,?,?)
        ON CONFLICT(owner,event_id) DO UPDATE SET status=excluded.status,rating=excluded.rating,
        confirmed_at=excluded.confirmed_at,answered_at=excluded.answered_at''',
        (owner, user_id, event.event_id, config.INTERACTION_TARGETS[action], rating,
         confirmed, answered))


def get_revision(connection, owner):
    """Return this owner's rating revision, zero before their first effective rating."""
    row = connection.execute('SELECT ratings_revision FROM settings WHERE owner=?',
                             (_owner(owner),)).fetchone()
    return row['ratings_revision'] if row is not None else 0


def get_favorites(connection, owner):
    """Return independent source series and club favorite sets for exactly one owner."""
    result = {'series': set(), 'club': set()}
    rows = connection.execute('SELECT kind,target_key FROM favorites WHERE owner=?',
                              (_owner(owner),)).fetchall()
    for row in rows:
        result[row['kind']].add(row['target_key'])
    return result


def set_favorite(connection, owner, kind, target_key, enabled):
    """Set one source-specific favorite idempotently without changing another owner."""
    owner = _owner(owner)
    prefixes = {'series': uniclubs_catalog.SERIES_PREFIX, 'club': uniclubs_catalog.CLUB_PREFIX}
    if not isinstance(kind, str) or kind not in prefixes or not isinstance(target_key, str):
        raise ValueError('A source series or club favorite is required.')
    prefix = prefixes[kind]
    if not target_key.startswith(prefix) or not target_key[len(prefix):].strip():
        raise ValueError('The favorite identifier has the wrong source namespace.')
    if type(enabled) is not bool:
        raise ValueError('Favorite enabled must be a boolean.')
    with connection:
        if enabled:
            connection.execute('''INSERT INTO favorites (owner,kind,target_key) VALUES (?,?,?)
                ON CONFLICT(owner,kind,target_key) DO NOTHING''', (owner, kind, target_key))
        else:
            connection.execute('DELETE FROM favorites WHERE owner=? AND kind=? AND target_key=?',
                               (owner, kind, target_key))


def clear_owner(connection, owner):
    """Remove only one owner's private plans, favorites and rating revision."""
    owner = _owner(owner)
    with connection:
        connection.execute('DELETE FROM plans WHERE owner=?', (owner,))
        connection.execute('DELETE FROM favorites WHERE owner=?', (owner,))
        connection.execute('DELETE FROM settings WHERE owner=?', (owner,))
